const cleanOutput = [];

for (const item of $input.all()) {
  const text = item.json.text || item.json.textAsHtml || item.json.snippet || '';

  // Extract fields
  const amountMatch = text.match(/INR\s*([\d,]+(?:\.\d{2})?)/i) || text.match(/(?:Rs\.?|₹)\s*([\d,]+(?:\.\d{2})?)/i);
  const recipientMatch = text.match(/towards\s+([A-Za-z0-9\s]+?)\s+through/i) || text.match(/(?:Paid to|To)\b\s*[:\-]?\s*([A-Za-z0-9\s]+)/i);
  const upiIdMatch = text.match(/([a-zA-Z0-9.\-_]+@[a-zA-Z0-9]+)/);
  const refMatch = text.match(/(?:UPI Reference Number|Ref No|Txn ID)\b\s*[:\-]?\s*(\d+)/i);

  // Extract and parse date (Format: YYYY-MM-DD)
  const dateMatch = text.match(/Date:\s*(\d{2}\/\d{2}\/\d{4})/i) || text.match(/(\d{2}-\d{2}-\d{4})/);
  let formattedDate = new Date().toISOString().split('T')[0]; // Default to today

  if (dateMatch) {
    const parts = dateMatch[1].split(/[\/-]/);
    if (parts.length === 3) {
      // Convert DD/MM/YYYY to YYYY-MM-DD
      formattedDate = `${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`;
    }
  }

  // Map directly to your MySQL table columns
  cleanOutput.push({
    json: {
      transaction_date: formattedDate,
      upi_ref_number: refMatch ? refMatch[1] : 'N/A',
      recipient_name: recipientMatch ? recipientMatch[1].trim() : 'Unknown',
      recipient_upi_id: upiIdMatch ? upiIdMatch[1] : 'N/A',
      amount: amountMatch ? parseFloat(amountMatch[1].replace(',', '')) : 0,
      payment_source: 'Kotak811 App'
    }
  });
}

return cleanOutput;
